#!/bin/bash

# Check if directory argument is provided
directory="$1"
if [ -z "$directory" ]; then
echo "Usage: $0 <directory>"
exit 1
fi

# Create results.txt in the input directory
results_file="$directory/results.txt"
touch $results_file

# Function to check class names in a file
check_class_names() {
  local file="$1"
  local violations=()

  # Use awk to process the file and find class definitions
  awk '{
    for (i=1; i<=NF; i++) {
      if ($i ~ /^class/) {
        # Extract class name
        class_name = substr($i, 7)

        # Check if class name starts with uppercase letter
        if (class_name ~ /^[A-Z][a-zA-Z0-9_]*/) {
          # Valid class name
        } else {
          # Invalid class name
          violations[++v_count] = "invalid class name '$class_name' at line " NR
        }
      }
    }
  }' $file > /dev/null 2>&1

  # Output results
  if [ ${#violations[@]} -eq 0 ]; then
    echo "$file PASSED"
    echo "$file PASSED" >> $results_file
  else
    echo "$file FAILED"
    echo "$file FAILED" >> $results_file

    for violation in "${violations[@]}";
    do
      echo "  $violation"
      echo "  $violation" >> $results_file
    done
  fi
}

# Find all .py files in the directory and process them
find $directory -type f -name "*.py" -exec bash -c 'check_class_names "$0"' {} \;

